def solve():
    import itertools
    for p in itertools.permutations(range(7)):
        if p[1] != 1:
            continue
        valid = True
        for d in range(1, 7):
            diffs = set()
            for i in range(7 - d):
                diff = p[i+d] - p[i]
                if diff in diffs:
                    valid = False
                    break
                diffs.add(diff)
            if not valid:
                break
        if valid:
            print(list(p))
            return
solve()
